// TestRoleVariable tests variable parsing
func TestRoleVariable(t *testing.T) {
	var tests = []struct {
		title string
		in    string
		err   error
		out   Expression
	}{
		{
			title: "no curly bracket prefix",
			in:    "external.foo}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid syntax",
			in:    `{{external.foo("bar")`,
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid variable syntax",
			in:    "{{internal.}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid dot syntax",
			in:    "{{external..foo}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "empty variable",
			in:    "{{}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "no curly bracket suffix",
			in:    "{{internal.foo",
			err:   trace.BadParameter(""),
		},
		{
			title: "too many levels of nesting in the variable",
			in:    "{{internal.foo.bar}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "valid with brackets",
			in:    `{{internal["foo"]}}`,
			out:   Expression{namespace: "internal", variable: "foo"},
		},
		{
			title: "string literal",
			in:    `foo`,
			out:   Expression{namespace: LiteralNamespace, variable: "foo"},
		},
		{
			title: "external with no brackets",
			in:    "{{external.foo}}",
			out:   Expression{namespace: "external", variable: "foo"},
		},
		{
			title: "internal with no brackets",
			in:    "{{internal.bar}}",
			out:   Expression{namespace: "internal", variable: "bar"},
		},
		{
			title: "internal with spaces removed",
			in:    "  {{  internal.bar  }}  ",
			out:   Expression{namespace: "internal", variable: "bar"},
		},
		{
			title: "variable with prefix and suffix",
			in:    "  hello,  {{  internal.bar  }}  there! ",
			out:   Expression{prefix: "hello,  ", namespace: "internal", variable: "bar", suffix: "  there!"},
		},
		{
			title: "variable with local function",
			in:    "{{email.local(internal.bar)}}",
			out:   Expression{namespace: "internal", variable: "bar", transform: emailLocalTransformer{}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.title, func(t *testing.T) {
			variable, err := Variable(tt.in)
			if tt.err != nil {
				assert.IsType(t, tt.err, err)
				return
			}
			assert.NoError(t, err)
			assert.Empty(t, cmp.Diff(tt.out, *variable, cmp.AllowUnexported(Expression{})))
		})
	}
}

func TestMatch(t *testing.T) {
	tests := []struct {
		name, expression string
		matches          []string
		misses           []string
	}{
		{"literal", "foo.bar", []string{"foo.bar"}, []string{"fooXbar", "xfoo.bar"}},
		{"wildcard", "foo*bar", []string{"foobar", "foo-middle-bar"}, []string{"xfoobar", "foobars"}},
		{"all", "*", []string{"", "anything"}, nil},
		{"raw regexp", "^foo[0-9]+$", []string{"foo12"}, []string{"xfoo12", "foo"}},
		{"regexp match", `{{regexp.match("foo")}}`, []string{"foo", "before foo after"}, []string{"bar"}},
		{"regexp quantifier", `{{regexp.match("^a{2}$")}}`, []string{"aa"}, []string{"a", "aaa"}},
		{"regexp not match", `{{regexp.not_match("foo")}}`, []string{"bar"}, []string{"foo", "before foo after"}},
		{"prefix suffix", `foo-{{regexp.match("bar")}}-baz`, []string{"foo-bar-baz", "foo-xxbarxx-baz"}, []string{"bar", "foo-bar", "foo-bar-baz-extra"}},
		{"overlapping prefix suffix", `ab{{regexp.match(".*")}}bc`, []string{"abbc"}, []string{"abc"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			matcher, err := Match(tt.expression)
			if !assert.NoError(t, err) {
				return
			}
			for _, in := range tt.matches {
				assert.True(t, matcher.Match(in), "input %q", in)
			}
			for _, in := range tt.misses {
				assert.False(t, matcher.Match(in), "input %q", in)
			}
		})
	}
}

func TestMatchErrors(t *testing.T) {
	tests := []struct {
		input, message string
	}{
		{`{{regexp.match("foo")`, `"{{regexp.match(\"foo\")" is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{expression}}`},
		{`{{other.match("foo")}}`, "unsupported function namespace other, supported namespaces are email and regexp"},
		{`{{regexp.other("foo")}}`, "unsupported function regexp.other, supported functions are: regexp.match, regexp.not_match."},
		{`{{email.other("foo")}}`, "unsupported function email.other, supported functions are: email.local"},
		{`{{regexp.match("[")}}`, `failed parsing regexp "[": error parsing regexp: missing closing ]: `},
		{`{{regexp.match()}}`, "regexp.match requires exactly one string literal argument"},
		{`{{regexp.match("a", "b")}}`, "regexp.match requires exactly one string literal argument"},
		{`{{regexp.match(external.foo)}}`, "regexp.match requires exactly one string literal argument"},
		{`{{email.local("foo")}}`, `"email.local(\"foo\")" is not a valid matcher expression - no variables and transformations are allowed`},
		{`{{external.foo}}`, `"external.foo" is not a valid matcher expression - no variables and transformations are allowed`},
		{`{{regexp.match("a") + regexp.match("b")}}`, `"regexp.match(\"a\") + regexp.match(\"b\")" is not a valid matcher expression - no variables and transformations are allowed`},
	}
	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			_, err := Match(tt.input)
			if assert.Error(t, err) {
				assert.True(t, trace.IsBadParameter(err))
				assert.True(t, strings.HasPrefix(err.Error(), tt.message), "got %q", err)
			}
		})
	}

	_, err := Variable(`{{regexp.match("foo")}}`)
	if assert.Error(t, err) {
		assert.EqualError(t, err, `matcher functions (like regexp.match) are not allowed here: "{{regexp.match(\"foo\")}}"`)
	}
}

// TestInterpolate tests variable interpolation
func TestInterpolate(t *testing.T) {
	type result struct {
		values []string
		err    error
	}
	var tests = []struct {
		title  string
		in     Expression
		traits map[string][]string
		res    result
	}{
		{
			title:  "mapped traits",
			in:     Expression{variable: "foo"},
			traits: map[string][]string{"foo": []string{"a", "b"}, "bar": []string{"c"}},
			res:    result{values: []string{"a", "b"}},
		},
		{
			title:  "mapped traits with email.local",
			in:     Expression{variable: "foo", transform: emailLocalTransformer{}},
			traits: map[string][]string{"foo": []string{"Alice <alice@example.com>", "bob@example.com"}, "bar": []string{"c"}},
			res:    result{values: []string{"alice", "bob"}},
		},
		{
			title:  "missed traits",
			in:     Expression{variable: "baz"},
			traits: map[string][]string{"foo": []string{"a", "b"}, "bar": []string{"c"}},
			res:    result{err: trace.NotFound("not found"), values: []string{}},
		},
		{
			title:  "traits with prefix and suffix",
			in:     Expression{prefix: "IAM#", variable: "foo", suffix: ";"},
			traits: map[string][]string{"foo": []string{"a", "b"}, "bar": []string{"c"}},
			res:    result{values: []string{"IAM#a;", "IAM#b;"}},
		},
		{
			title:  "error in mapping traits",
			in:     Expression{variable: "foo", transform: emailLocalTransformer{}},
			traits: map[string][]string{"foo": []string{"Alice <alice"}},
			res:    result{err: trace.BadParameter("")},
		},
		{
			title:  "literal expression",
			in:     Expression{namespace: LiteralNamespace, variable: "foo"},
			traits: map[string][]string{"foo": []string{"a", "b"}, "bar": []string{"c"}},
			res:    result{values: []string{"foo"}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.title, func(t *testing.T) {
			values, err := tt.in.Interpolate(tt.traits)
			if tt.res.err != nil {
				assert.IsType(t, tt.res.err, err)
				assert.Empty(t, values)
				return
			}
			assert.NoError(t, err)
			assert.Empty(t, cmp.Diff(tt.res.values, values))
		})
	}
}

